ALTER TABLE `_ecommerce_customer_accounts` ADD `email_canonical` text GENERATED ALWAYS AS ((CASE WHEN instr(lower(trim(email_normalized)), '@') < 2 OR rtrim(substr(lower(trim(email_normalized)), instr(lower(trim(email_normalized)), '@') + 1), '.') = '' THEN NULL
    WHEN rtrim(substr(lower(trim(email_normalized)), instr(lower(trim(email_normalized)), '@') + 1), '.') IN ('gmail.com', 'googlemail.com') THEN replace((CASE WHEN instr(substr(lower(trim(email_normalized)), 1, instr(lower(trim(email_normalized)), '@') - 1), '+') > 1 THEN substr(substr(lower(trim(email_normalized)), 1, instr(lower(trim(email_normalized)), '@') - 1), 1, instr(substr(lower(trim(email_normalized)), 1, instr(lower(trim(email_normalized)), '@') - 1), '+') - 1) ELSE substr(lower(trim(email_normalized)), 1, instr(lower(trim(email_normalized)), '@') - 1) END), '.', '') || '@gmail.com'
    ELSE (CASE WHEN instr(substr(lower(trim(email_normalized)), 1, instr(lower(trim(email_normalized)), '@') - 1), '+') > 1 THEN substr(substr(lower(trim(email_normalized)), 1, instr(lower(trim(email_normalized)), '@') - 1), 1, instr(substr(lower(trim(email_normalized)), 1, instr(lower(trim(email_normalized)), '@') - 1), '+') - 1) ELSE substr(lower(trim(email_normalized)), 1, instr(lower(trim(email_normalized)), '@') - 1) END) || '@' || rtrim(substr(lower(trim(email_normalized)), instr(lower(trim(email_normalized)), '@') + 1), '.') END)) VIRTUAL;--> statement-breakpoint
